args.new_string:
void freeBlockInBuffer(unsigned char *blk, Buffer *buf)
{
	/* The availability flag byte sits right before the payload. */
	blk -= 1;
	*blk = BLOCK_AVAILABLE;
	buf->numFreeBlk++;
}

