args.new_string:
unsigned char *readBlockFromDisk(unsigned int addr, Buffer *buf)
{
	char filename[40];
	unsigned char *blkPtr;
	FILE *fp;

	sprintf(filename, "%d.blk", addr);
	if ((fp = fopen(filename, "rb")) == NULL)
	{
		fprintf(stderr, "Reading Block %u Fails!\n", addr);
		return NULL;
	}

	if ((blkPtr = getNewBlockInBuffer(buf)) == NULL)
	{
		fclose(fp);
		return NULL;
	}

	if (fread(blkPtr, 1, buf->blkSize, fp) != buf->blkSize)
	{
		fprintf(stderr, "Reading Block %u Fails!\n", addr);
		freeBlockInBuffer(blkPtr, buf);
		fclose(fp);
		return NULL;
	}

	fclose(fp);
	buf->numIO++;
	return blkPtr;
}

