args.new_string:
void readTuplesFromBlock(unsigned char *blk, Relation *R)
{
	/* A relation block stores TUPLE_PER_BLK tuples, each being two
	 * 4-byte integers, followed by 4 unused bytes and the address
	 * of the next block.
	 */
	for (int i = 0; i < TUPLE_PER_BLK; i++)
	{
		memcpy(&R[i].attr1, blk + i * 2 * sizeof(int), sizeof(int));
		memcpy(&R[i].attr2, blk + (i * 2 + 1) * sizeof(int), sizeof(int));
	}
}

