int readHashFromBlock(unsigned char *blk, Relation *R)
{
	/* Hash-bucket blocks store up to HASH_PER_BLK tuples followed by
	 * the number of valid tuples at byte offset HASH_PER_BLK * 8.
	 */
	int count;

	memcpy(&count, blk + HASH_PER_BLK * 2 * sizeof(int), sizeof(int));
	if (count < 0 || count > HASH_PER_BLK)
		return 0;

	for (int i = 0; i < count; i++)
	{
		memcpy(&R[i].attr1, blk + i * 2 * sizeof(int), sizeof(int));
		memcpy(&R[i].attr2, blk + (i * 2 + 1) * sizeof(int), sizeof(int));
	}

	return count;
}

