args.new_string:
	/* Pass 2: merge all runs in a single multi-way merge. One buffer
	 * block holds the current head block of each run; the merged
	 * tuples are flushed to retAddr through the shared writer.
	 */
	int runBlks[8];          /* blocks per run */
	int curBlk[8];           /* current block index inside each run */
	int curTuple[8];         /* current tuple index inside each run */
	Relation heads[8][TUPLE_PER_BLK];
	unsigned char *headBlk[8];

	pushToWrite(buf, NULL, 0, retAddr, true);

	for (int i = 0; i < numRuns; i++) /* load the first block of every run */
	{
		runBlks[i] = blkNum - i * segBlks < segBlks ? blkNum - i * segBlks : segBlks;
		curBlk[i] = 0;
		curTuple[i] = 0;
		headBlk[i] = readBlockFromDisk(segAddr + i * segBlks, buf);
		if (headBlk[i] == NULL)
			return -1;
		readTuplesFromBlock(headBlk[i], heads[i]);
	}

	while (true)
	{
		int best = -1;

		for (int i = 0; i < numRuns; i++) /* find the smallest run head */
		{
			if (curBlk[i] >= runBlks[i])
				continue;
			if (best == -1 || heads[i][curTuple[i]].attr1 < heads[best][curTuple[best]].attr1)
				best = i;
		}
		if (best == -1)
			break;

		pushToWrite(buf, (unsigned char *)&heads[best][curTuple[best]], sizeof(Relation), retAddr);

		curTuple[best]++;
		if (curTuple[best] == TUPLE_PER_BLK) /* head block exhausted */
		{
			freeBlockInBuffer(headBlk[best], buf);
			curBlk[best]++;
			curTuple[best] = 0;
			if (curBlk[best] < runBlks[best])
			{
				headBlk[best] = readBlockFromDisk(segAddr + best * segBlks + curBlk[best], buf);
				if (headBlk[best] == NULL)
					return -1;
				readTuplesFromBlock(headBlk[best], heads[best]);
			}
		}
	}

	pushToWrite(buf, NULL, 0, retAddr, false, true);

	return 0;
}

