static vector<string> splitConds(const string &info)
{
	/* Split a compound predicate list on '&' and trim each piece. */
	vector<string> conds;
	size_t start = 0;

	while (start <= info.size())
	{
		size_t amp = info.find('&', start);
		string piece = (amp == string::npos)
			? info.substr(start)
			: info.substr(start, amp - start);
		piece = trimStr(piece);
		if (!piece.empty())
			conds.push_back(piece);
		if (amp == string::npos)
			break;
		start = amp + 1;
	}
	return conds;
}

static string condAttr(const string &cond)
{
	/* The attribute a predicate talks about precedes the '='. */
	size_t eq = cond.find('=');
	return trimStr(cond.substr(0, eq));
}

static bool attrMatchesRel(const string &attr, const string &rel)
{
	/* Heuristic: an attribute belongs to the relation sharing its
	 * initial letter (ENAME->EMPLOYEE, DNAME->DEPARTMENT, ...).
	 */
	return !attr.empty() && !rel.empty() && attr[0] == rel[0];
}

TreeNode *optimizeQuery(TreeNode *root, vector<string> info)
{
	if (root == NULL)
		return NULL;

	if (root->type == "SELECT")
	{
		/* Split compound predicates and carry the conditions down;
		 * the SELECT node itself is re-created as low as possible.
		 */
		vector<string> conds = splitConds(root->info);
		info.insert(info.end(), conds.begin(), conds.end());
		return optimizeQuery(root->left, info);
	}

	if (root->type == "PROJECTION")
	{
		/* Conditions collected above sink below the projection. */
		root->left = optimizeQuery(root->left, info);
		return root;
	}

	if (root->type == "JOIN")
	{
		/* Route each pending condition to the side whose relation
		 * owns the predicate attribute; unmatched ones go left.
		 */
		vector<string> leftConds, rightConds;
		string leftRel = root->left ? root->left->info : "";
		string rightRel = root->right ? root->right->info : "";

		for (size_t i = 0; i < info.size(); i++)
		{
			string attr = condAttr(info[i]);
			bool lm = attrMatchesRel(attr, leftRel);
			bool rm = attrMatchesRel(attr, rightRel);

			if (rm && !lm)
				rightConds.push_back(info[i]);
			else
				leftConds.push_back(info[i]);
		}

		root->left = optimizeQuery(root->left, leftConds);
		root->right = optimizeQuery(root->right, rightConds);
		return root;
	}

	/* LEAF: wrap the relation in one SELECT per pending condition,
	 * keeping the textual predicate order outermost-first.
	 */
	TreeNode *node = root;
	for (int i = (int)info.size() - 1; i >= 0; i--)
	{
		TreeNode *sel = new TreeNode("SELECT", info[i]);
		sel->left = node;
		node = sel;
	}
	return node;
}

